<script setup lang="ts">
import { t as tr } from '../../i18n';

import { onMounted, ref } from 'vue';
import { api } from '../../api/client';
import type { components } from '../../api/generated/admin';
import { credits, consumerDate } from './consumer-format';
type Code=components['schemas']['ConsumerCode'];
const codes=ref<Code[]>([]),plans=ref<components['schemas']['ConsumerPlan'][]>([]),generated=ref<string[]>([]);
const kind=ref('balance'),amount=ref('10'),concurrency=ref(1),planID=ref(''),count=ref(1),days=ref(30),busy=ref(false),error=ref('');
async function load(){const [c,p]=await Promise.all([api('/admin/api/consumer/codes'),api('/admin/api/consumer/plans')]);codes.value=c.codes;plans.value=p.plans;}
async function generate(){if(busy.value)return;busy.value=true;error.value='';generated.value=[];try{if(!/^\d+(\.\d{1,8})?$/.test(amount.value))throw new Error(tr('额度最多支持 8 位小数'));const [a,b='']=amount.value.split('.');const units=Number(BigInt(a!)*100000000n+BigInt(b.padEnd(8,'0')));if(!Number.isSafeInteger(units))throw new Error(tr('额度超出范围'));const d=await api('/admin/api/consumer/codes',{method:'POST',body:{action:'generate',count:count.value,template:{kind:kind.value,amount:units,concurrency:concurrency.value,plan_id:planID.value,expires_at:Math.floor(Date.now()/1000)+days.value*86400}}});generated.value=d.codes??[];await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function disable(id:string){if(busy.value)return;busy.value=true;error.value='';try{await api('/admin/api/consumer/codes',{method:'POST',body:{action:'disable',id}});await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>error.value=(e as Error).message));
</script>
<template><div class="consumer-form"><h3>{{tr('生成兑换码')}}</h3><form @submit.prevent="generate"><div class="field-grid cols-2"><div class="field"><label for="ConsumerCodesSelect1">{{tr('类型')}}</label><select id="ConsumerCodesSelect1" v-model="kind"><option value="balance">{{tr('额度')}}</option><option value="concurrency">{{tr('并发增量')}}</option><option value="subscription">{{tr('套餐订阅')}}</option></select></div><div v-if="kind==='balance'" class="field"><label>{{tr('参考 USD 额度')}}<input v-model="amount" inputmode="decimal" required></label></div><div v-if="kind==='concurrency'" class="field"><label>{{tr('增加并发数')}}<input v-model.number="concurrency" type="number" min="1" max="1024" required></label></div><div v-if="kind==='subscription'" class="field"><label for="ConsumerCodesSelect2">{{tr('套餐')}}</label><select id="ConsumerCodesSelect2" v-model="planID" required><option disabled value="">{{tr('选择套餐')}}</option><option v-for="p in plans.filter(x=>x.enabled)" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div class="field"><label>{{tr('生成数量')}}<input v-model.number="count" type="number" min="1" max="100" required></label></div><div class="field"><label>{{tr('兑换有效天数')}}<input v-model.number="days" type="number" min="1" max="3650" required></label></div></div><button class="btn primary" :disabled="busy">{{tr('生成兑换码')}}</button></form>
<div v-if="generated.length"><p class="hint">{{tr('完整兑换码仅本次显示，请复制保存。')}}</p><textarea :value="generated.join('\n')" readonly rows="5" :aria-label="tr('新生成的兑换码')" class="mono"></textarea><button class="btn" @click="generated=[]">{{tr('隐藏完整兑换码')}}</button></div>
<div class="table-wrap"><table><thead><tr><th>{{tr('兑换码')}}</th><th>{{tr('权益')}}</th><th>{{tr('状态')}}</th><th>{{tr('截止时间')}}</th><th>{{tr('使用者')}}</th><th>{{tr('操作')}}</th></tr></thead><tbody><tr v-for="c in codes.slice().reverse()" :key="c.id"><td>{{c.hint}}</td><td>{{c.kind==='balance'?credits(c.amount)+' USD':c.kind==='concurrency'?tr('并发 +')+c.concurrency:plans.find(p=>p.id===c.plan_id)?.name}}</td><td>{{c.used_by?tr('已使用'):c.disabled?tr('已停用'):c.expires_at<Date.now()/1000?tr('已过期'):tr('可兑换')}}</td><td>{{consumerDate(c.expires_at)}}</td><td>{{c.used_by||'—'}}</td><td><button class="btn xs" :disabled="busy||c.disabled||!!c.used_by" @click="disable(c.id)">{{tr('停用')}}</button></td></tr></tbody></table></div><p v-if="error" class="err-text" role="alert">{{error}}</p></div></template>
